{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure no account can have a negative balance through secure transaction validation.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-01", "TRU-04"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall allow withdrawals only when sufficient funds are available across both accounts.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-02", "RES-05"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-03",
      "text": "The system shall inform users of insufficient funds before transaction processing.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-03", "TRU-06"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-04",
      "text": "The system shall log all transactions with date, time, type, amount, and resulting balance.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-04", "TRU-03"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-05",
      "text": "The system shall implement secure PIN verification for user authentication.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-05", "TRU-02"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-06",
      "text": "The system shall provide a mechanism for safe degradation during maintenance, allowing limited withdrawals.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-06"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall provide users with a clear summary of account status after each transaction.",
      "quality_axes": ["Safety", "Trustworthiness"],
      "derived_from": ["SAF-07"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-08",
      "text": "The ATM system shall process transactions within 3 seconds to ensure user responsiveness.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall maintain a transaction throughput of at least 100 transactions per minute.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The ATM application shall optimize data retrieval to minimize latency when accessing transaction history.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The ATM system shall automatically shut down during periods of inactivity to save energy.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The ATM system shall provide an option for clients to receive electronic transaction records instead of paper receipts.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The system shall assess the environmental impact of its operations annually and report findings to stakeholders.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-07"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall ensure that all transactions are encrypted during transmission.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall maintain user privacy by securely encrypting all personal and financial data.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["RES-07"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
